```csharp
public static bool AreAnagrams(string str1, string str2)
{
    // Step 1: Remove spaces and convert to lowercase
    str1 = str1.Replace(" ", "").ToLower();
    str2 = str2.Replace(" ", "").ToLower();

    // Step 2: Check lengths
    if (str1.Length != str2.Length)
    {
        return false;
    }

    // Step 3: Convert to character arrays
    char[] charArray1 = str1.ToCharArray();
    char[] charArray2 = str2.ToCharArray();

    // Step 4: Sort character arrays
    Array.Sort(charArray1);
    Array.Sort(charArray2);

    // Step 5: Compare sorted arrays
    for (int i = 0; i < charArray1.Length; i++)
    {
        if (charArray1[i] != charArray2[i])
        {
            return false;
        }
    }

    // Step 6: If all characters match, they are anagrams
    return true;
}
```

