    'o': 'g',
    'u': 'h'
  };

  // Create a mapping from positions to vowels
  const positionToVowel = {
    'a': 'a',
    'c': 'e',
    'd': 'i',
    'f': 'o',
    'g': 'u',
    'h': 'a'
  };

  // Create a mapping from letters to their encoded counterparts
  const letterToEncoded = {
    'a': 'c',
    'e': 'd',
    'i': 'f',
    'o': 'g',
    'u': 'h'
  };

  // Convert the message to uppercase (since the function will switch case)
  const uppercaseMessage = message.toUpperCase();

  // Initialize an empty array to store encoded characters
  const encodedChars = [];

  // Iterate through each character in the message
  for (const char of uppercaseMessage) {
    // If the character is a vowel, replace it with the corresponding letter
    if (vowels.includes(char)) {
      encodedChars.push(vowelToPosition[char]);
    } else {
      // If the character is not a vowel, substitute it with the two-letter position
      const position = char.charCodeAt(0) - 'a'.charCodeAt(0) + 2;
      encodedChars.push(positionToVowel[position]);
