def carrier_concentration(electron_conc, hole_conc, intrinsic_conc):
    # Check for negative values
    if any(val < 0 for val in [electron_conc, hole_conc, intrinsic_conc]):
        raise ValueError("All concentrations must be non-negative.")

    # Count how many concentrations are zero
    zero_count = sum(1 for val in [electron_conc, hole_conc, intrinsic_conc] if val == 0)

    # Check if exactly one concentration is zero
    if zero_count != 1:
        raise ValueError("Exactly one of the concentrations must be zero.")

    # Determine which concentration to calculate
    if electron_conc == 0:
        if hole_conc == 0 or intrinsic_conc == 0:
            raise ValueError("Cannot calculate electron concentration if hole or intrinsic concentration is zero.")
        electron_conc = intrinsic_conc ** 2 / hole_conc
        return ("Electron Concentration", electron_conc)
    elif hole_conc == 0:
        if electron_conc == 0 or intrinsic_conc == 0:
            raise ValueError("Cannot calculate hole concentration if electron or intrinsic concentration is zero.")
        hole_conc = intrinsic_conc ** 2 / electron_conc
        return ("Hole Concentration", hole_conc)
    elif intrinsic_conc == 0:
        if electron_conc == 0 or hole_conc == 0:
            raise ValueError("Cannot calculate intrinsic concentration if electron or hole concentration is zero.")
        intrinsic_conc = (electron_conc * hole_conc) ** 0.5
        return ("Intrinsic Concentration", intrinsic_conc)
    else:
        raise ValueError("More than one concentration is zero.")
